// resposta da API de Responses: procura o item "message" dentro de output[] e pega
// o texto; usa output_text como atalho se existir.
const resp = $input.first().json;
let texto = resp.output_text || '';
if (!texto && Array.isArray(resp.output)) {
  const msg = resp.output.find(o => o.type === 'message');
  if (msg && Array.isArray(msg.content) && msg.content[0]) texto = msg.content[0].text || '';
}
let candidatos = [];
try {
  const match = texto.match(/\[[\s\S]*\]/);
  candidatos = match ? JSON.parse(match[0]) : [];
} catch (e) {
  candidatos = [];
}
if (!Array.isArray(candidatos)) candidatos = [];
const base = $('Extrair Corpo Fornecedores').first().json;
return [{ json: { ...base, candidatos } }];

const item = $input.first().json;
return item.candidatos.map(c => ({ json: {
  resumo_id: item.resumo_id,
  nome_fornecedor: c.nome_fornecedor || null,
  site: c.site || null,
  contato: c.contato || null
} }));

const parsed = $('Parse Fornecedores').first().json;
const usuario = $input.first().json;
const candidatos = parsed.candidatos || [];
let texto;
if (!candidatos.length) {
  texto = '🔎 Busquei fornecedores pra "' + parsed.tipo_produto + '" mas nao achei nenhum candidato confiavel no momento. Recomendo pesquisar manualmente ou tentar de novo mais tarde.';
} else {
  const lista = candidatos.map((c, i) => (i + 1) + '. ' + (c.nome_fornecedor || 'sem nome') +
    (c.site ? ' — ' + c.site : '') + (c.contato ? ' (' + c.contato + ')' : '')).join('\n');
  texto = '🔎 Possiveis fornecedores para: ' + parsed.tipo_produto + '\n\n' + lista +
    '\n\nIsso e so uma lista de descoberta -- confira e entre em contato manualmente antes de fechar qualquer negocio.';
}
return [{ json: { numero: (usuario.whatsapp_numero || '').replace(/\D/g, ''), texto } }];
